"""Selected, attributed excerpts and campaign-aware notes for the first road chapter."""
import json

def build(page,pages,between,dehyphen,flat,out):
    sections=[]
    def add(id,title,kicker,summary,body,sources=None,extracts=None):
        sections.append(dict(id=id,title=title,kicker=kicker,summary=summary,body=body,sources=sources or [],extracts=extracts or []))
    def excerpt(book,ns,title,text):
        return dict(book='Проклятье Страда' if book=='original' else 'Повышение ставок',pages=', '.join(map(str,ns)),title=title,text=dehyphen(text))
    add('start','Перед выходом из деревни','ПРОЧИТАТЬ СНАЧАЛА',
        'Короткая опора для ближайшей игры. Примерно пять минут на этот раздел; дальше — подробности и книжные фрагменты.',
        '''<div class="campaign-box"><strong>В вашей кампании уже принято</strong><ul><li>Страд ещё не кусал Ирину: используем постепенное уничтожение её опор из «Повышения ставок».</li><li>Донавич тайно кормит Дору жителями. Последствия расследования зависят от того, что действительно сделали герои.</li><li>Герои выбрались из Дома смерти; Нарима вернулась изменённой. Её одержимость — ваша линия, которой в книгах нет.</li></ul></div>
<h3>Маршрут ближайшего отрезка</h3><p>Деревня Баровия → каменный мост через Ивлис → перекрёсток с виселицей (F) → северо-западная тропа вниз к реке → лагерь у озера Тсер (G). Направление на Валлаки/Равенлофт — другая, юго-западная дорога вверх.</p>
<h3>Что подготовить до старта</h3><ul><li>Выясни, похоронен ли Колян: в оригинале Ирина не уезжает до похорон.</li><li>Определи, кто идёт: Ирина, Исмарк, приглашённые проводники. Их присутствие меняет разговоры и встречи.</li><li>Уточни время суток, отдых, припасы и выбранный масштаб карты. Утро в деревне не означает автоматического наступления ночи у лагеря.</li><li>Выбери одну дорожную сцену, приготовь видение на виселице и гадание. Добавлять несколько обязательных боёв для этого пути не требуется.</li></ul>
<h3>Удобный порядок сцен — предложение ведущему</h3><p>Короткий разговор с Ириной в дороге → встреча с путниками или наблюдающим вороном → перекрёсток и повешенный → контрастный тёплый лагерь → история у костра → мадам Ева. Игроки могут свернуть, задержаться или отказаться от гадания.</p>''',
        ['Оригинал: PDF 36–38, 46–49.','Повышение ставок: PDF 5, 7, 16.'])

    add('road','Дорога и время в пути','ПЕРЕМЕЩЕНИЕ',
        'Не смешивай два масштаба карты. На коротком отрезке до Тсер важнее понятный маршрут, чем искусственная ночёвка.',
        '''<h3>Два книжных масштаба</h3><div class="table-scroll"><table><thead><tr><th>Вариант</th><th>Гекс</th><th>При обычном темпе</th></tr></thead><tbody><tr><td>Исходная карта</td><td>¼ мили</td><td>Около 5 минут на гекс</td></tr><tr><td>«Повышение ставок»</td><td>¾ мили</td><td>Около 15 минут на гекс</td></tr></tbody></table></div><p>Переработка увеличивает линейные расстояния втрое, а площадь — в девять раз. Её вступительная формулировка о площади непоследовательна; сами размеры и гексы дают именно это соотношение. Выбор масштаба в вашей кампании пока не закреплён.</p>
<h3>Как считать ваш переход</h3><p>Посчитай гексы вдоль реально выбранной дороги от точки выхода до лагеря, умножь на время гекса и отдельно прибавь остановки. Не измеряй по прямой через лес. Поворот к Тсер — спуск к реке, а не подъём на мост над водопадом.</p><p>По правилам путешествия D&amp;D 5e 2014 обычный темп пешком — 3 мили в час, медленный — 2, быстрый — 4. За стандартные восемь часов это 24, 18 и 30 миль. Пересечённая местность замедляет путь; медленный темп позволяет скрываться, быстрый ухудшает пассивное Восприятие. Это правила путешествия, а не скорость токена в бою.</p>
<h3>Дневной свет и туман</h3><p>Баровийский день остаётся ярким светом для зрения, но не считается солнечным светом против вампиров. Поэтому день не делает их механически безвредными. Обычный лесной туман не получает автоматически свойств смертельных пограничных Туманов.</p>''',
        ['Оригинал: PDF 25 — дневной свет. Карта земель Баровии: исходный масштаб.','Повышение ставок: PDF 5 — изменение масштаба; PDF 7 — частота встреч.','D&D Basic Rules 2014, Adventuring — Travel Pace.'],
        [excerpt('raising',[5],'Масштаб и хозяйство долины',page('raising',5)),excerpt('original',[25],'Солнечный свет в Баровии',between(page('original',25),'Солнечный свет в Баровии','Изменения в магии'))])

    add('ireena','Ирина: как вести её в дороге','ПЕРСОНАЖ РЯДОМ С ГРУППОЙ',
        'Сдержанная, но волевая. Она помогает спасать себя и не знает всех ответов о собственном прошлом.',
        '''<h3>Что действительно дано в оригинале</h3><p>Молодая женщина с тёмно-рыжими волосами; законно-добрая, использует статблок дворянина с 14 хитами. Кажущаяся кротость сочетается с крепкой волей. Она старается помогать группе всем, чем может. Не делай из слова «дворянин» ни полноценный боевой класс, ни доказательство беспомощности.</p><p>Её детские воспоминания обрывочны. Она не знает, как оказалась у Коляна, и не осознаёт себя Татьяной. Недавние нападения волков и других существ известны ей лично; дальние тайны долины — нет.</p><h3>Что поменять для вашей версии</h3><p>Не переносить в её рассказ два укуса и связанные с ними вампирские чары из оригинала. Здесь осада дома должна лишить её чувства безопасности. Страд стремится разрушить поддержку, чтобы замок показался единственным выходом. Это мотив Страда для ведущего; Ирина не обязана уже понимать всю стратегию.</p><h3>Что она может обсуждать</h3><ul><li>Отца и то, как они с Исмарком сами сколотили гроб.</li><li>Ночи осады, соседей, которые перестали приходить, желание самой выбирать, куда ехать.</li><li>Своё отношение к помощи героев: благодарность не требует безусловного подчинения.</li><li>Реакцию на Нариму. Подозрение или сочувствие здесь — твой авторский выбор, а не книжное знание об одержимости.</li></ul><h3>Манера — предложение для отыгрыша</h3><p>Вежливо благодарит за конкретное дело; замечает усталость спутника; просит объяснить риск; при попытке распоряжаться ею становится холоднее. Может сама предложить перевязать рану, расспросить местного или помочь с вещами. Это способы показать книжную волю, а не новые способности.</p>''',
        ['Оригинал: PDF 43, 46–47, 49.','Повышение ставок: PDF 7.'],
        [excerpt('original',[47],'Отыгрыш Ирины — исходная версия с укусами',between(page('original',47),'Отыгрыш Ирины','Е5. Церковь')),excerpt('raising',[7],'Страд и Ирина — используемая стратегия',between(page('raising',7),'Страд и Ирина','Случайные Столкновения'))])

    add('ireena-secrets','Ирина: тайны и дальнейшие связи','ТОЛЬКО ВЕДУЩЕМУ',
        'Это знания для подготовки. Ни Ирина, ни Исмарк не обязаны знать их сейчас.',
        '''<h3>Татьяна и семья</h3><p>Ирина — новое воплощение души Татьяны, возлюбленной Сергея, которую преследовал Страд. Колян нашёл девочку у края Сваличского леса возле Столпа Равенлофта и удочерил. Донавич знает историю её появления в семье.</p><p>Айзек Стражни в Валлаки — её родной брат. Они не знают об этом родстве. Айзек видит её во снах, заказывает Блинскому похожих кукол и при встрече пытается забрать её силой. Безопасный город не равен отсутствию новых угроз.</p><h3>Приготовленная могила</h3><p>В замке уже есть пустая крипта №18 с именем Ирины и обозначением «жена». Это демонстрирует, что Страд видит в обращении и заточении исполнение своей любви.</p><h3>Церковь Святого Андрала</h3><p>В «Повышении ставок» Анастасия знает, что брат и сестра надеются на защиту церкви, и готовит убийство Ирины после кражи костей. Это её собственный замысел, а не приказ Страда. Переработка предлагает растянуть событие до десяти дней после прибытия героев в Валлаки; не запускай таймер сейчас по умолчанию.</p><h3>Позже: Крезк</h3><p>Оригинальное событие у священного пруда способно увести Ирину вместе с Сергеем. Переработка оставляет ей собственную жизнь: она вспоминает прошлые воплощения, выбирает остаться Ириной и бороться. На PDF 56 предложены новые статблоки прошлых жизней: священник, разведчик с 40 хитами, берсерк, шпион с 40 хитами, рыцарь — без автоматической выдачи соответствующих оружия и брони. Это поздняя развилка, ещё не решение вашей кампании.</p>''',
        ['Оригинал: PDF 49; 66 — портрет Татьяны; 87 — крипта; 104, 115 — куклы; 224 — Айзек.','Повышение ставок: PDF 46 — Анастасия; 55–56 — Крезк.'],
        [excerpt('original',[224],'Айзек: коллекционер кукол и родство',between(page('original',224),'Коллекционер кукол.','Черты Айзека Стражни')),excerpt('raising',[55],'Крезк: пересмотренная встреча с прошлым',between(page('raising',55),'Что-то Синее - Пересмотренное'))])

    add('crossroads','Перекрёсток у реки Ивлис','ОБЛАСТЬ F',
        'Виселица, одиннадцать безымянных могил и выбор дороги. Видение появляется, когда герои уходят.',
        '''<h3>Что лежит перед героями</h3><p>Подгнивший помост высотой 5 футов, старая виселица с обрывком верёвки, дорожный указатель. Позади — низкая разрушенная ограда и 11 могил с пустыми надгробиями. В могилах останки казнённых: прогнившие гробы и кости.</p><ul><li><strong>Восток:</strong> деревня Баровия через каменный мост.</li><li><strong>Северо-запад:</strong> озеро Тсер, тропа спускается к лагерю.</li><li><strong>Юго-запад:</strong> дорога поднимается к водопаду, далее к Равенлофту и Валлаки.</li></ul><h3>Встреча и проводники</h3><p>При входе в F книга требует проверить случайное столкновение, если с героями нет вистани. Это проверка, а не обязательное сражение. Проводники-вистани ведут к своему лагерю.</p><h3>Когда они уходят</h3><p>Раздаётся скрип. На прежде пустой виселице теперь тело. Случайно выбранный герой видит собственный труп, остальные — незнакомого баровийца. Тело кажется настоящим и пахнет смертью, но от прикосновения или перемещения рассыпается в прах. Не объявляй это неизбежным будущим и не заставляй всех видеть одного героя.</p><h3>Если здесь выпало сокровище</h3><p>Оно лежит в одной из могил; при последовательном раскапывании шанс нахождения растёт на 10 процентных пунктов за каждую могилу. Указание на символ или слова конкретного героя в этой сцене — отдельный совет из вашего издания. Не добавляй сокровище сюда без соответствующего результата расклада.</p>''',
        ['Оригинал: PDF 36–37, области D и F.'],
        [excerpt('original',[36],'Река Ивлис и перекрёсток',between(page('original',36),'D. Река Ивлис')),excerpt('original',[37],'Могилы и повешенный',between(page('original',37),end='G. Лагерь у Озера Тсер'))])

    add('encounters','Как выбирать дорожные встречи','ПРАВИЛА И РИТМ',
        'Таблица оригинала не сбалансирована под один уровень. Встреча не всегда означает бой.',
        '''<h3>Оригинальная процедура</h3><p>Каждые 30 минут пути: к20, на дороге событие происходит на 18+, в глуши — на 15+. После двух случайных столкновений вне стен за 12 часов новые проверки не делают. Если событие произошло, бросают <strong>к12 + к8</strong> по дневной или ночной таблице. Это не к20: средние результаты встречаются чаще.</p><h3>Переработка</h3><p>«Повышение ставок» рекомендует выбирать и адаптировать встречи заранее, чтобы они раскрывали сюжет. При втрое увеличенных расстояниях предлагает проверки через 90 минут. Не объединяй выбранную сцену и все случайные броски без оглядки на нагрузку.</p><h3>Для вашей ближайшей дороги — предложение</h3><p>После насыщенной деревни можно взять одну социальную сцену: вистани или охотники. Виселица даст тревогу, лагерь — отдых и информацию. Если нужны волки, заранее покажи слежку и пути отступления. Не выдавай полную стаю из книжной таблицы за лёгкую разминку для 2–3-го уровня.</p><h3>Кого не нужно автоматически превращать во врага</h3><p>Скелет-всадник ищет выход из Баровии и игнорирует мирных путников. Охотники ищут пропавшего. Верворон наблюдает и может помогать. Берсерки стараются уйти, пока им не угрожают. Вистани могут разговаривать и предлагать проводничество.</p>''',
        ['Оригинал: PDF 30–35.','Повышение ставок: PDF 7.'],
        [excerpt('original',[30],'Процедура и обе таблицы встреч',between(page('original',30),'Случайные столкновения','Используйте описания')),excerpt('raising',[7],'Выбор встреч под сюжет',between(page('raising',7),'Случайные Столкновения','Новые Столкновения'))])

    add('meeting-vistani','Вистани на дороге','ГОТОВАЯ КНИЖНАЯ ВСТРЕЧА',
        '1к4+1 путников; разговор, проводники, защита от волков — и возможные соглядатаи Страда.',
        '''<p>Оригинальная встреча описывает 1к4+1 вистани со статблоком разбойника. Они смеются, рассказывают страшные истории, охотятся на мелкую дичь или ищут могилы для грабежа. Запах табака и голоса можно заметить раньше самих путников.</p><p>Эта конкретная группа служит Страду. Это свойство встречи, а не утверждение о каждом представителе народа.</p><h3>Условия проводничества</h3><p>Книжная цена — 100 зм. Пока они идут с группой, для столкновений в глуши бросается к12 вместо к12+к8; волки и лютые волки не угрожают группе, если вистани сопровождают её добровольно, а не как пленники. Это не право героев выйти из долины.</p><h3>Что можно показать в разговоре</h3><p>Путники знают направление к лагерю и мадам Еве. Охотно расспрашивают, откуда герои, что видели и с кем идут. Имена и личные истории конкретных дорожных вистани здесь не заданы: придуманные тобой имена не станут книжными фактами.</p><p>Один из них несёт 2к4 небольших самоцвета по 50 зм. Это личное имущество из встречи, а не гарантированный ассортимент торговца или жемчужина нужной стоимости.</p>''',
        ['Оригинал: PDF 30 — количество; PDF 33 — описание и услуги.'],
        [excerpt('original',[33],'Разбойники-вистани на дороге',between(page('original',33),'Р азбойники Вистани','Р азведчики Баровии'))])

    add('meeting-menu','Другие встречи: что они означают','БЕЗ ОБЯЗАТЕЛЬНОГО БОЯ',
        'Короткие карточки для выбора; ниже — полные соответствующие страницы из вашего издания.',
        '''<h3>Охотники и пропавший</h3><p>Разведчики сначала держат оружие наготове, затем просят помощи. Возможные имена пропавших в вашем издании: Бьянка Попеску, Милош Радоневич, Иван Казин, Бореслава Кшижинская. Это не обязательно жертва Донавича: связь с текущим расследованием придётся выбрать тебе.</p><h3>Всадник-скелет</h3><p>Едет на скелете боевого коня с потухшим фонарём. Оба погибли, пытаясь покинуть долину; теперь ищут выход. Пока на них не нападают, они проходят мимо.</p><h3>Ворон и слежка</h3><p>Верворон из Хранителей Пера наблюдает за группой 1к4 часа и затем докладывает своим. Повторная встреча может дать приглашение в «Синюю Воду» в Валлаки. Не путай такого наблюдателя со шпионом Страда.</p><p>У Страда есть отдельная сеть зверей и людей: доклады на рассвете и закате, наблюдение, попытки украсть личный предмет для магической слежки. Так он может узнавать о группе, не будучи лично в каждой сцене.</p><h3>Капкан</h3><p>Передние путники могут заметить его проверкой Выживания Сл 15. Сработавший капкан требует спасброска Ловкости Сл 13; 1к4 колющего урона, остановка движения и цепь. Высвобождение действием: Сила Сл 13; неудача причиняет ещё 1 урон.</p><h3>Не для обязательного старта</h3><p>Перевёрнутый дилижанс Василия в переработке расположен <strong>между мельницей и Валлаки</strong>. Сцена друида с раненым вервороном предпочтительна после знакомства с Валлаки. Их можно перенести авторским решением, но они не стоят по книге между деревней и Тсер.</p>''',
        ['Оригинал: PDF 31–35.','Повышение ставок: PDF 6–8.'],
        [excerpt('original',[31,32,33,34,35],'Подробные дорожные встречи — справочник',pages('original',range(31,36))),excerpt('raising',[7,8],'Дополнительные сцены переработки',between(pages('raising',[7,8]),'Новые Столкновения'))])

    add('camp','Лагерь у озера Тсер','ОБЛАСТЬ G',
        'Музыка, вино и живые голоса после деревенского страха. Гостеприимство не означает полной откровенности.',
        '''<h3>Что видно</h3><p>Грязная колея между деревьями выходит к воде. Четыре крытых фургона стоят кольцом, рядом пять небольших ярких шатров. Большой освещённый шатёр мадам Евы — у берега. Восемь упряжных лошадей пьют из реки. За лагерем тропа продолжается вдоль берега.</p><h3>Кто здесь</h3><p>У костра 12 вистани со статблоками разбойников. В исходном тексте они пьяны и имеют помеху на атаки и проверки. Ещё три трезвых капитана разбойников отдыхают в фургонах и реагируют на тревогу. Числа нужны на случай конфликта, а не как приглашение к бою.</p><p>Они союзны Страду, но при мирном поведении приглашают героев к костру и угощают вином. Если гости торопятся, сообщают: мадам Ева ждала их прихода. Проводники, доставившие героев, остаются в лагере.</p><h3>Отдых и торговля</h3><p>Книга предлагает отдых у костра, но не фиксирует ни бесплатную отдельную комнату, ни обязательный ассортимент лавки. Ночёвку, еду, цену и безопасность можно обсудить в сцене. Богатства в таблице сокровищ лагеря — имущество его обитателей, а не прайс-лист на продажу.</p><h3>Что здесь не перепутать</h3><p>Это лагерь мадам Евы. Луваш, Арригал, Арабэлль и сумеречные эльфы относятся к другому лагерю возле Валлаки. Не переноси их сюда незаметно для собственной подготовки.</p>''',
        ['Оригинал: PDF 37–38.'],
        [excerpt('original',[37],'Прибытие и состав лагеря',between(page('original',37),'G. Лагерь у Озера Тсер')),excerpt('original',[38],'Гостеприимство и приглашение',between(page('original',38),end='История Вистани'))])

    add('vistani-lore','О чём говорить с вистани','ЗНАНИЯ, ПОВЕРЬЯ, СЕКРЕТЫ',
        'Их рассказ — не всеведущая лекция. Книга отдельно называет факты, верования и ложные заявления.',
        '''<h3>Они не единая партия злодеев</h3><p>Вистани путешествуют семьями, сохраняют ремёсла и обычаи, почитают старших. Среди них есть слуги Страда и люди с другими целями. Народ обязан своей свободой передвижения давнему спасению Страда ещё при его жизни.</p><h3>Информация после завоевания доверия</h3><ul><li>Страд — древняя нежить; у него была возлюбленная Татьяна. О её судьбе обычные рассказчики могут не знать.</li><li>Замок назван в честь Равеновии, долина — в честь Барова.</li><li>Три главных поселения связаны Сваличской дорогой; с дороги опасно сходить.</li><li>Души умерших остаются в Баровии. Мадам Ева считается выдающейся предсказательницей.</li><li>Старую мельницу советуют обходить, не обязательно объясняя причину.</li></ul><h3>Где верование, а где обман</h3><p>Поверье о душах внутри воронов в книге прямо отмечено как неверное. Продаваемые «зелья от тумана» не действуют. Способность вистани проходить границу не передаётся автоматически сопровождаемым героям.</p><h3>Проклятия и сглаз</h3><p>Это реальные способности, но не универсальное наказание за любой неудобный вопрос. В тексте проклятие — воздаяние за несправедливость; снятие вызывает психический откат на наложившего. Для точной механики и вариантов смотри фрагмент ниже. Не используй всё перечисленное как случайные способности одного NPC без решения, что у него действительно есть.</p>''',
        ['Оригинал: PDF 28–30.'],
        [excerpt('original',[28,29],'Народ вистани и их молва',pages('original',[28,29])),excerpt('original',[30],'Сглаз',between(page('original',30),end='Случайные столкновения'))])

    add('story','История у костра','ЗАЦЕПКА К БОЛЬШОЙ КАМПАНИИ',
        'Год назад могущественный маг уже пытался поднять народ против Страда. По словам свидетеля, он проиграл.',
        '''<p>Один из вистани рассказывает о волшебнике, который собрал мятежников и привёл их к замку. При появлении вампира почти все разбежались. Дуэль продолжилась над водопадом: маг выдержал камни и молнию, но затем сорвался вниз. Рассказчик искал тело и ценности, но река уже унесла мага.</p><p>Он не помнит имени, лишь впечатление, что оно было важным. Для ведущего: это связь с Безумным магом у горы Бараток. Слова очевидца о гибели не доказывают реальную смерть.</p><p>История позволяет ненавязчиво связать Дору и прошлое восстание, показать цену прямого похода на замок и направить внимание к мадам Еве. Не превращай рассказ в доказательство, что герои заведомо проиграют.</p>''',
        ['Оригинал: PDF 38; область M — Безумный маг.'],
        [excerpt('original',[38],'Рассказ вистани целиком',between(page('original',38),'История Вистани','Шатёр Мадам Евы'))])

    add('eva','Мадам Ева','ВСТРЕЧА И МОТИВЫ',
        'Она знает имена и некоторые прошлые поступки гостей, но не разъясняет все тайны долины.',
        '''<h3>В шатре</h3><p>Красноватое волшебное пламя, чёрная ткань на столе, хрустальный шар, смех старухи. Ева встречает героев так, будто давно ждала; называет каждого по имени и вспоминает его дела. Для этого бери сыгранные события из вашей кампании, не придумывай за игроков новые проступки.</p><p>Она спрашивает, хотят ли они узнать судьбу. Отказ возможен: книга советует тогда пользоваться ранее подготовленным раскладом. Ева не должна блокировать выход из лагеря до согласия.</p><h3>Правда для ведущего</h3><p>Её настоящее имя — Катарина. Она дочь короля Барова и женщины-вистани, сводная сестра Страда; он этого не знает. Служила в Равенлофте и была при трагедии Сергея и Татьяны. Сделка с Матерью Ночи дала ей предвидение и облик нестареющей старухи.</p><p>Она стремится освободить Страда от проклятия; готова искать тех, кто уничтожит его или займёт его место. Её идеал и привязанность к вистани не делают её бескорыстной покровительницей героев: чужие судьбы она может рассматривать как средство. Скрывает происхождение даже от своих.</p>''',
        ['Оригинал: PDF 38 и 229.'],
        [excerpt('original',[38],'Шатёр мадам Евы',between(page('original',38),'Шатёр Мадам Евы','Сокровища')),excerpt('original',[229],'Мадам Ева: предыстория и черты',between(page('original',229),'Мадам Ева','Оживленные объекты'))])

    add('reading','Гадание: порядок и колоды','ПАМЯТКА ЗА СТОЛОМ',
        'Пять карт общего расклада. Личные предсказания — отдельный этап после него.',
        '''<p><a class="reader-card-link" href="tarokka.html">Открыть листалку всех 54 карт →</a></p><ol><li><strong>Том Страда.</strong> Младшая колода: где лежит книга.</li><li><strong>Святой символ Равенкинд.</strong> Младшая колода: где лежит символ.</li><li><strong>Солнечный меч.</strong> Младшая колода: где лежит меч.</li><li><strong>Союзник.</strong> Старшая колода: кто поможет против Страда.</li><li><strong>Страд.</strong> Старшая колода: место гарантированной встречи в замке.</li></ol><p>Старшая колода — 14 карт с короной. Младшая — 40: по 10 мечей, звёзд, монет и глифов. В младшей каждой масти есть 1–9 и мастер. Мастер соответствует десятке обычной колоды.</p><h3>Как использовать листалку</h3><p>Открой нужную колоду, тапни карту. Сначала прочитай общее значение, затем выбери «Сокровище», «Союзник» или «Страд в замке». Варианты одной карты сохранены отдельно. «Мой расклад» хранит выбранные пять карт на твоём устройстве; это подготовка, а не уже произошедшее гадание.</p><h3>Не подменяй символическое значение точной разгадкой</h3><p>Например, карта Палача может означать осуждение и смерть вообще, но в позиции союзника оригинального расклада она указывает на Исмарка. В позиции Страда эта же карта описывает другое место. Подсказки и ответы в листалке зависят от роли карты.</p><h3>Что ещё не выбрано у вас</h3><p>Согласована идея общего гадания, затем отдельных личных предсказаний. Предварительные личные карты: Корво — Призрак; Джари — Донжон или Искуситель; Нарима — Пастух; Рататуй — Член гильдии. Это черновик, не закреплённый расклад. Не исключай их из колод молча.</p><p>«Повышение ставок» для своей вводной предлагает заранее отложить личные карты. Применение этого правила меняет состав общего расклада и требует осознанного решения. Твоя уже сыгранная вводная не обязана целиком повторять его сценарий.</p>''',
        ['Оригинал: PDF 13–19, 241–242; иллюстрации PDF 243–248.','Повышение ставок: PDF 9–10.','Кампания: предварительные личные карты в заметках подготовки, не окончательный выбор.'],
        [excerpt('original',[13,14],'Порядок общего расклада',between(pages('original',[13,14]),'Предсказания Р авенлофта','Р асположение Сокровищ')),excerpt('raising',[9,10],'Личные карты и предсказания',between(pages('raising',[9,10]),'Судьба Ждет','Первая Сессия'))])

    add('after-camp','После лагеря: не перепутать высоту','НА СЛЕДУЮЩИЙ ОТРЕЗОК',
        'Тропа от лагеря ведёт к основанию водопада. Мост находится высоко над ней.',
        '''<p>Из лагеря можно пройти вдоль реки к нижней части каньона и увидеть мост примерно в тысяче футов над головой. Это не незаметный короткий подъём на верхнюю дорогу.</p><p>Верхняя дорога идёт от перекрёстка F к области H. Сам мост мокрый, но безопасен для обычного пересечения; мшистые горгульи — простые статуи. Стены каньона отвесные и скользкие: книга требует магию или набор скалолаза для восхождения.</p><p>Если группа после гадания выбирает Валлаки, покажи необходимость вернуться на верхний маршрут или осознанно искать иной способ. Не телепортируй её с берега озера на мост, не объяснив путь.</p>''',
        ['Оригинал: PDF 38, область H.'],
        [excerpt('original',[38],'Водопад Тсер: оба уровня',between(page('original',38),'H. Водопад Тсер'))])

